UPDATE message_report
SET status = #{status}
WHERE id = #{id} AND status = 0

UPDATE review
SET comment_count = (
    SELECT COUNT(1) FROM review_comment rc
    WHERE rc.review_id = review.id AND rc.status = 1 AND rc.is_deleted = FALSE
)
WHERE id = (
    SELECT rc.review_id FROM review_comment rc WHERE rc.id = #{commentId}
)

UPDATE post
SET comment_count = (
    SELECT COUNT(1) FROM post_comment pc
    WHERE pc.post_id = post.id AND pc.status = 1 AND pc.is_deleted = FALSE
)
WHERE id = (
    SELECT pc.post_id FROM post_comment pc WHERE pc.id = #{commentId}
)
